window.__ADRIAN_GUIDE_CSS__ = "/* Adrian (SOMA Guide engine) — portable floating assistant */\n\n/* ── Widget root ── */\n#soma-guide {\n  position: fixed;\n  z-index: 9999;\n  bottom: 28px;\n  right: 28px;\n  font-family: 'Georgia', serif;\n  font-size: 15px;\n  color: #060e18;\n  user-select: text;\n}\n/* SOMA principle: all content text is selectable (scrape, don't screenshot).\n * Only the chrome (drag handle + buttons) opts out, to avoid selecting on drag. */\n.sg-header, .sg-fab, .sg button, .sg-suggest-chip, .sg-suggest-more { user-select: none; }\n\n/* ── FAB (minimized state) ── */\n.sg-fab {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  background: #c9a84c;\n  color: #060e18;\n  border: none;\n  border-radius: 50px;\n  padding: 12px 20px 12px 14px;\n  font-family: inherit;\n  font-size: 0.88rem;\n  font-weight: 600;\n  letter-spacing: 0.03em;\n  cursor: pointer;\n  box-shadow: 0 4px 20px rgba(0,0,0,0.22);\n  transition: transform 0.15s, box-shadow 0.15s;\n}\n.sg-fab:hover { transform: translateY(-2px); box-shadow: 0 6px 24px rgba(0,0,0,0.28); }\n.sg-fab-avatar { font-size: 1.2rem; line-height: 1; }\n.sg-fab-name { line-height: 1; }\n\n/* ── Panel ── */\n.sg-panel {\n  display: none;\n  flex-direction: column;\n  background: rgba(255, 255, 255, 0.93);\n  backdrop-filter: blur(10px);\n  -webkit-backdrop-filter: blur(10px);\n  border-radius: 14px;\n  box-shadow: 0 8px 40px rgba(0,0,0,0.18), 0 2px 8px rgba(0,0,0,0.08);\n  overflow: hidden;\n  border: 1px solid rgba(0,0,0,0.08);\n}\n\n/* ── Mode: minimized ── */\n.sg--min .sg-panel { display: none; }\n.sg--min .sg-fab   { display: flex; }\n\n/* ── Mode: idle ── */\n.sg--idle .sg-fab  { display: none; }\n.sg--idle .sg-panel {\n  display: flex;\n  width: 340px;\n  max-height: min(520px, 85vh);\n}\n\n/* ── Mode: text ── */\n.sg--text .sg-fab  { display: none; }\n.sg--text .sg-panel {\n  display: flex;\n  width: 360px;\n  height: 480px;\n  resize: none;\n  overflow: hidden;\n}\n\n/* ── Mode: walkthrough ── */\n.sg--walkthrough .sg-fab  { display: none; }\n.sg--walkthrough .sg-panel {\n  display: flex;\n  width: 340px;\n  max-height: min(520px, 85vh);\n}\n\n/* ── Mode: voice ── */\n.sg--voice .sg-fab  { display: none; }\n.sg--voice .sg-panel {\n  display: flex;\n  width: 248px;\n}\n\n/* Mode containers (idle / voice / text / walkthrough / tour bar) are switched\n * via the `hidden` attribute in JS. Their own `display:flex/block` rules would\n * otherwise override `hidden` and stack every mode at once — make `hidden` win. */\n.sg [hidden] { display: none !important; }\n\n/* When an inline form (feedback/action) is active, focus on it: hide the chat\n * scrollback so the form isn't buried below history that's irrelevant to filling it. */\n.sg-messages--focus > :not(.sg-feedback-form) { display: none; }\n\n/* ── Resize handles (all four corners, with cursor + hover hint) ── */\n.sg-resize-h { position: absolute; width: 14px; height: 14px; z-index: 6; }\n.sg--min .sg-resize-h { display: none; }\n.sg-resize-nw { top: 0; left: 0;  cursor: nwse-resize; }\n.sg-resize-ne { top: 0; right: 0; cursor: nesw-resize; }\n.sg-resize-sw { bottom: 0; left: 0;  cursor: nesw-resize; }\n.sg-resize-se { bottom: 0; right: 0; cursor: nwse-resize; }\n.sg-resize-h::after { content: ''; position: absolute; width: 7px; height: 7px; opacity: 0; transition: opacity 0.12s; }\n.sg-resize-h:hover::after { opacity: 1; border: 2px solid #c9a84c; }\n.sg-resize-nw:hover::after { top: 3px; left: 3px; border-right: 0; border-bottom: 0; }\n.sg-resize-ne:hover::after { top: 3px; right: 3px; border-left: 0; border-bottom: 0; }\n.sg-resize-sw:hover::after { bottom: 3px; left: 3px; border-right: 0; border-top: 0; }\n.sg-resize-se:hover::after { bottom: 3px; right: 3px; border-left: 0; border-top: 0; }\n/* keep header controls clickable above the top-corner handles */\n.sg-header-btns, .sg-persona { position: relative; z-index: 7; }\n\n/* ── Header ── */\n.sg-header {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  padding: 12px 14px;\n  background: #060e18;\n  color: #fff;\n  cursor: grab;\n  border-radius: 14px 14px 0 0;\n}\n.sg-header:active { cursor: grabbing; }\n\n.sg-persona {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  /* Let the persona block shrink so a long name (e.g. \"Quinn · Review\") can never\n   * push the header buttons — including Close (×) — off the edge of a narrow panel. */\n  min-width: 0;\n  flex: 1 1 auto;\n  overflow: hidden;\n}\n.sg-persona-avatar { font-size: 1.1rem; flex-shrink: 0; }\n.sg-persona-name {\n  font-size: 0.9rem;\n  font-weight: 600;\n  letter-spacing: 0.04em;\n  color: #c9a84c;\n  /* Truncate instead of overflowing the header. */\n  min-width: 0;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n.sg-version {\n  font-size: 0.6rem;\n  font-family: monospace;\n  opacity: 0.38;\n  color: #c9a84c;\n  align-self: flex-end;\n  padding-bottom: 1px;\n  letter-spacing: 0.02em;\n}\n\n.sg-header-btns {\n  display: flex;\n  gap: 4px;\n  /* Never shrink or wrap — keep all controls (incl. Close ×) visible at any width. */\n  flex: 0 0 auto;\n  flex-wrap: nowrap;\n  margin-left: 8px;\n}\n.sg-header-btns button {\n  background: none;\n  border: none;\n  color: rgba(255,255,255,0.6);\n  font-size: 1rem;\n  cursor: pointer;\n  padding: 4px 6px;\n  border-radius: 6px;\n  line-height: 1;\n  transition: color 0.15s, background 0.15s;\n}\n.sg-header-btns button:hover {\n  color: #fff;\n  background: rgba(255,255,255,0.12);\n}\n\n/* Close (×) button — more prominent than the minimize (−) */\n.sg-btn-close {\n  color: rgba(255,255,255,0.85) !important;\n  font-size: 1.2rem !important;\n  padding: 2px 8px !important;\n  min-width: 28px;\n  min-height: 28px;\n}\n.sg-btn-close:hover {\n  color: #fff !important;\n  background: rgba(255,255,255,0.18) !important;\n}\n\n/* ── Body ── */\n.sg-body {\n  padding: 16px;\n  flex: 1;\n  overflow-y: auto;\n  min-height: 0;\n}\n\n/* ── Idle UI ── */\n.sg-greeting {\n  font-size: 0.92rem;\n  line-height: 1.6;\n  color: #333;\n  margin: 0 0 14px;\n}\n.sg-topic-list {\n  display: flex;\n  flex-direction: column;\n  gap: 6px;\n  margin-bottom: 12px;\n}\n.sg-topic-btn {\n  background: #f5f1e8;\n  border: 1px solid #e8dfc4;\n  border-radius: 8px;\n  padding: 8px 12px;\n  font-family: inherit;\n  font-size: 0.84rem;\n  color: #060e18;\n  cursor: pointer;\n  text-align: left;\n  transition: background 0.15s, border-color 0.15s;\n}\n.sg-topic-btn:hover {\n  background: #ede7d3;\n  border-color: #c9a84c;\n}\n\n/* ── Suggestion chips (conversational shell) ── */\n.sg-suggest {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 6px;\n  padding: 4px 2px 10px;\n}\n.sg-suggest-chip,\n.sg-suggest-more {\n  background: #f5f1e8;\n  border: 1px solid #e8dfc4;\n  border-radius: 999px;\n  padding: 5px 12px;\n  font-family: inherit;\n  font-size: 0.78rem;\n  color: #060e18;\n  cursor: pointer;\n  transition: background 0.15s, border-color 0.15s;\n}\n.sg-suggest-chip:hover,\n.sg-suggest-more:hover {\n  background: #ede7d3;\n  border-color: #c9a84c;\n}\n.sg-suggest-more {\n  background: transparent;\n  border-color: transparent;\n  color: #5f5e5a;\n  text-decoration: underline;\n  text-decoration-style: dotted;\n}\n\n/* Tell → Show offer buttons */\n.sg-offer { display: flex; gap: 8px; }\n.sg-offer-show, .sg-offer-tell {\n  border-radius: 8px; padding: 7px 14px; font-family: inherit; font-size: 0.82rem; cursor: pointer;\n}\n.sg-offer-show { background: #102036; color: #c9a84c; border: none; font-weight: 600; }\n.sg-offer-show:hover { background: #1a3050; }\n.sg-offer-do { background: #c9a84c; color: #0d1b2a; border: none; font-weight: 600; }\n.sg-offer-do:hover { background: #b8962f; }\n.sg-offer-tell { background: transparent; color: #5f5e5a; border: 1px solid #d9d5c8; }\n.sg-offer-tell:hover { border-color: #c9a84c; color: #060e18; }\n\n/* Output-mode toggle (Text / Voice) — the explicit \"how should Bill answer\" choice.\n * On first encounter the Voice option pulses to announce \"you can talk to me\",\n * then quiets once the user has engaged.\n * Lives at panel level (sibling of .sg-header / .sg-body), NOT inside the\n * scrollable .sg-body — pinned so it can never scroll out of the clip box. */\n.sg-io-toggle { display: flex; gap: 6px; padding: 10px 14px 0; flex: 0 0 auto; }\n.sg-io-btn {\n  flex: 1;\n  border: 1px solid #d9d5c8;\n  background: #f5f1e8;\n  color: #5f5e5a;\n  border-radius: 999px;\n  padding: 7px 10px;\n  font-family: inherit;\n  font-size: 0.82rem;\n  cursor: pointer;\n}\n.sg-io-btn--active { background: #102036; color: #c9a84c; border-color: #102036; font-weight: 600; }\n.sg-io-voice--pulse { border-color: #c9a84c; animation: sg-voice-pulse 2.2s ease-in-out infinite; }\n@keyframes sg-voice-pulse {\n  0%, 100% { box-shadow: 0 0 0 0 rgba(201,168,76,0.5); }\n  50%      { box-shadow: 0 0 0 6px rgba(201,168,76,0); }\n}\n\n/* ── Voice UI ── */\n.sg-voice-ui {\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  padding: 24px 16px;\n  gap: 12px;\n}\n.sg-orb {\n  width: 64px;\n  height: 64px;\n  border-radius: 50%;\n  background: radial-gradient(circle at 38% 38%, #c9a84c, #8b6c2a);\n  box-shadow: 0 0 0 0 rgba(201, 168, 76, 0.5);\n  animation: sg-breathe 2.4s ease-in-out infinite;\n  cursor: pointer;\n  -webkit-tap-highlight-color: transparent;\n  transition: width 0.35s cubic-bezier(0.4, 0, 0.2, 1),\n              height 0.35s cubic-bezier(0.4, 0, 0.2, 1);\n}\n/* Active state: orb shrinks to a small indicator so transcript text can read clearly */\n.sg-orb--active {\n  width: 36px;\n  height: 36px;\n}\n.sg-orb.sg-orb--speaking {\n  animation: sg-pulse 0.6s ease-in-out infinite;\n}\n@keyframes sg-breathe {\n  0%, 100% { box-shadow: 0 0 0 0 rgba(201,168,76,0.4); }\n  50%       { box-shadow: 0 0 0 12px rgba(201,168,76,0.0); }\n}\n@keyframes sg-pulse {\n  0%, 100% { transform: scale(1); box-shadow: 0 0 0 4px rgba(201,168,76,0.3); }\n  50%       { transform: scale(1.08); box-shadow: 0 0 0 10px rgba(201,168,76,0.0); }\n}\n.sg-voice-status {\n  font-size: 0.82rem;\n  color: #666;\n  margin: 0;\n  text-align: center;\n}\n.sg-voice-transcript {\n  font-size: 0.92rem;\n  color: #1a1a1a;\n  margin: 4px 0 0;\n  text-align: center;\n  line-height: 1.6;\n  min-height: 0;\n  padding: 0;\n  word-break: break-word;\n  transition: background 0.2s, padding 0.2s;\n}\n.sg-voice-transcript:not(:empty) {\n  background: #f5f1e8;\n  border-radius: 8px;\n  border-left: 3px solid #c9a84c;\n  padding: 10px 14px;\n  text-align: left;\n}\n\n/* ── Text UI ── */\n.sg-text-ui {\n  display: flex;\n  flex-direction: column;\n  height: 100%;\n}\n.sg-messages {\n  flex: 1;\n  overflow-y: auto;\n  display: flex;\n  flex-direction: column;\n  gap: 8px;\n  margin-bottom: 10px;\n  padding-right: 2px;\n}\n.sg-msg {\n  max-width: 85%;\n  padding: 8px 12px;\n  border-radius: 10px;\n  font-size: 0.88rem;\n  line-height: 1.55;\n  word-break: break-word;\n}\n.sg-msg--user {\n  background: #060e18;\n  color: #fff;\n  align-self: flex-end;\n  border-radius: 10px 10px 2px 10px;\n}\n.sg-msg--agent {\n  background: #f5f1e8;\n  color: #060e18;\n  align-self: flex-start;\n  border-radius: 10px 10px 10px 2px;\n  user-select: text;\n  -webkit-user-select: text;\n  position: relative;\n}\n\n/* Copy button — appears on hover/focus-within */\n.sg-msg--agent .sg-copy-btn {\n  position: absolute;\n  top: 4px;\n  right: 4px;\n  background: rgba(255,255,255,0.85);\n  border: 1px solid rgba(201,168,76,0.4);\n  border-radius: 5px;\n  padding: 2px 7px;\n  font-size: 0.7rem;\n  color: #7a5e1a;\n  cursor: pointer;\n  opacity: 0;\n  transition: opacity 0.15s, background 0.15s;\n  line-height: 1.5;\n  font-family: inherit;\n  pointer-events: none;\n}\n.sg-msg--agent:hover .sg-copy-btn,\n.sg-msg--agent:focus-within .sg-copy-btn {\n  opacity: 1;\n  pointer-events: auto;\n}\n.sg-msg--agent .sg-copy-btn:hover {\n  background: #fff8e7;\n  border-color: #c9a84c;\n}\n.sg-msg--agent .sg-copy-btn--copied {\n  color: #2a7a3a;\n  border-color: rgba(42,122,58,0.4);\n}\n.sg-input-bar {\n  display: flex;\n  gap: 6px;\n  border-top: 1px solid #eee;\n  padding-top: 10px;\n}\n.sg-input {\n  flex: 1;\n  border: 1px solid #ddd;\n  border-radius: 8px;\n  padding: 8px 10px;\n  font-family: inherit;\n  font-size: 0.88rem;\n  outline: none;\n  transition: border-color 0.15s;\n}\n.sg-input:focus { border-color: #c9a84c; }\n.sg-send {\n  background: #c9a84c;\n  border: none;\n  border-radius: 8px;\n  padding: 8px 12px;\n  color: #060e18;\n  font-size: 1rem;\n  cursor: pointer;\n  font-weight: bold;\n  transition: background 0.15s;\n}\n.sg-send:hover { background: #b8963e; }\n\n/* ── Mic (voice input) button ── */\n.sg-mic {\n  background: none;\n  border: 1px solid #ddd;\n  border-radius: 8px;\n  padding: 6px 8px;\n  font-size: 0.9rem;\n  cursor: pointer;\n  opacity: 0.75;\n  transition: opacity 0.15s, background 0.15s, border-color 0.15s;\n}\n.sg-mic:hover { opacity: 1; background: #fff8e7; border-color: #c9a84c; }\n.sg-mic--listening {\n  opacity: 1;\n  background: #fff0f0;\n  border-color: #d9534f;\n  animation: sg-mic-pulse 0.9s ease-in-out infinite;\n}\n@keyframes sg-mic-pulse {\n  0%, 100% { box-shadow: 0 0 0 0 rgba(217,83,79,0.35); }\n  50%       { box-shadow: 0 0 0 5px rgba(217,83,79,0); }\n}\n\n/* ── Web-search toggle ── */\n.sg-web-toggle {\n  background: none;\n  border: 1px solid #ddd;\n  border-radius: 8px;\n  padding: 6px 8px;\n  font-size: 0.9rem;\n  cursor: pointer;\n  opacity: 0.45;\n  transition: opacity 0.15s, background 0.15s, border-color 0.15s;\n  flex-shrink: 0;\n}\n.sg-web-toggle:hover { opacity: 0.75; }\n.sg-web-toggle--on {\n  opacity: 1;\n  background: #fff8e7;\n  border-color: #c9a84c;\n}\n\n/* ── Inference thinking indicator ── */\n.sg-msg--thinking {\n  opacity: 0.55;\n  font-style: italic;\n  letter-spacing: 0.2em;\n  animation: sg-pulse 1.2s ease-in-out infinite;\n}\n@keyframes sg-pulse {\n  0%, 100% { opacity: 0.35; }\n  50%       { opacity: 0.75; }\n}\n\n/* ── \"Show me where\" action bubble ── */\n.sg-msg--action {\n  align-self: flex-start;\n  background: none;\n  padding: 0;\n  max-width: 100%;\n}\n.sg-show-me-btn {\n  background: none;\n  border: 1px solid #c9a84c;\n  border-radius: 16px;\n  padding: 5px 14px;\n  font-size: 0.82rem;\n  color: #7a5e1a;\n  cursor: pointer;\n  font-family: inherit;\n  transition: background 0.15s;\n}\n.sg-show-me-btn:hover { background: #fff8e7; }\n\n/* ── Walkthrough UI ── */\n.sg-wt-ui {\n  display: flex;\n  flex-direction: column;\n  gap: 10px;\n}\n.sg-wt-narration {\n  font-size: 0.92rem;\n  line-height: 1.6;\n  color: #1a1a1a;\n  margin: 0;\n  background: #f5f1e8;\n  padding: 12px;\n  border-radius: 8px;\n  border-left: 3px solid #c9a84c;\n}\n.sg-wt-instruction {\n  font-size: 0.83rem;\n  line-height: 1.55;\n  color: #555;\n  margin: 0;\n  font-style: italic;\n}\n\n/* ── TTS narration bar ── */\n.sg-tts-bar {\n  display: flex;\n  gap: 6px;\n  justify-content: flex-end;\n  margin-top: 2px;\n}\n.sg-btn-icon {\n  background: none;\n  border: 1px solid rgba(201, 168, 76, 0.35);\n  border-radius: 5px;\n  color: #c9a84c;\n  cursor: pointer;\n  font-family: inherit;\n  font-size: 0.82rem;\n  line-height: 1;\n  padding: 3px 7px;\n  transition: background 0.15s, border-color 0.15s;\n}\n.sg-btn-icon:hover {\n  background: rgba(201, 168, 76, 0.14);\n  border-color: #c9a84c;\n}\n\n/* ── Walkthrough bar (Next/Exit controls) ── */\n.sg-wt-bar {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  padding: 10px 14px;\n  border-top: 1px solid #eee;\n  background: #fafafa;\n}\n.sg-wt-menu {\n  background: none;\n  border: 1px solid #ddd;\n  border-radius: 6px;\n  padding: 4px 9px;\n  font-size: 0.78rem;\n  cursor: pointer;\n  color: #555;\n  transition: border-color 0.15s, color 0.15s;\n}\n.sg-wt-menu:hover { border-color: #999; color: #333; }\n.sg-wt-exit {\n  background: none;\n  border: 1px solid #ddd;\n  border-radius: 6px;\n  padding: 5px 10px;\n  font-family: inherit;\n  font-size: 0.8rem;\n  cursor: pointer;\n  color: #666;\n  transition: border-color 0.15s, color 0.15s;\n}\n.sg-wt-exit:hover { border-color: #999; color: #333; }\n.sg-wt-prog {\n  flex: 1;\n  text-align: center;\n  font-size: 0.78rem;\n  color: #999;\n}\n.sg-wt-next {\n  background: #060e18;\n  border: none;\n  border-radius: 6px;\n  padding: 5px 14px;\n  font-family: inherit;\n  font-size: 0.82rem;\n  color: #c9a84c;\n  font-weight: 600;\n  cursor: pointer;\n  transition: background 0.15s;\n}\n.sg-wt-next:hover { background: #1a2a3a; }\n\n/* ── Resume bar ── */\n.sg-resume-bar {\n  padding: 12px 14px;\n  border-top: 1px solid #eee;\n  background: #fafafa;\n}\n.sg-resume-bar > p {\n  font-size: 0.82rem;\n  color: #555;\n  margin: 0 0 8px;\n}\n.sg-resume-steps {\n  display: flex;\n  flex-direction: column;\n  gap: 2px;\n  margin-bottom: 8px;\n  max-height: 200px;\n  overflow-y: auto;\n  scrollbar-width: thin;\n  scrollbar-color: #c9a84c transparent;\n}\n.sg-resume-steps::-webkit-scrollbar { width: 4px; }\n.sg-resume-steps::-webkit-scrollbar-thumb { background: rgba(201,168,76,0.45); border-radius: 2px; }\n.sg-resume-btns { display: flex; gap: 6px; flex-wrap: wrap; }\n.sg-wt-resume {\n  background: #060e18;\n  border: none;\n  border-radius: 6px;\n  padding: 4px 14px;\n  font-family: inherit;\n  font-size: 0.82rem;\n  color: #c9a84c;\n  font-weight: 600;\n  cursor: pointer;\n  transition: background 0.15s;\n}\n.sg-wt-resume:hover { background: #1a2a3a; }\n.sg-wt-restart,\n.sg-wt-home {\n  background: none;\n  border: 1px solid #ddd;\n  border-radius: 6px;\n  padding: 4px 10px;\n  font-family: inherit;\n  font-size: 0.8rem;\n  cursor: pointer;\n  color: #666;\n}\n.sg-wt-restart:hover,\n.sg-wt-home:hover { border-color: #999; color: #333; }\n\n/* ── Page element highlight ── */\n.sg-highlight {\n  outline: 3px solid #c9a84c !important;\n  outline-offset: 4px;\n  border-radius: 4px !important;\n  box-shadow: 0 0 0 8px rgba(201, 168, 76, 0.18), 0 0 20px rgba(201, 168, 76, 0.35) !important;\n  position: relative;\n  z-index: 1000;\n  transition: outline 0.25s ease, box-shadow 0.25s ease;\n}\n/* Inline elements (e.g. <a> in nav) need a block context to show the full ring */\n.sg-highlight[data-sg-was-inline] {\n  display: inline-block !important;\n}\n\n/* ── Demo cursor ── */\n.sg-demo-cursor {\n  position: fixed;\n  pointer-events: none;\n  z-index: 99999;\n  width: 20px;\n  height: 24px;\n  opacity: 0;\n  transition: left 0.7s cubic-bezier(0.4, 0, 0.2, 1),\n              top  0.7s cubic-bezier(0.4, 0, 0.2, 1),\n              opacity 0.2s;\n}\n.sg-demo-cursor--visible {\n  opacity: 1;\n}\n.sg-demo-cursor svg {\n  display: block;\n  filter: drop-shadow(1px 2px 3px rgba(0,0,0,0.45));\n}\n\n/* Click ripple animation */\n.sg-demo-ripple {\n  position: fixed;\n  pointer-events: none;\n  z-index: 99998;\n  width: 28px;\n  height: 28px;\n  border-radius: 50%;\n  background: rgba(201, 168, 76, 0.55);\n  animation: sg-ripple 0.65s ease-out forwards;\n}\n@keyframes sg-ripple {\n  to { transform: scale(3.5); opacity: 0; }\n}\n\n/* Generic dropdown open class used by demo cursor */\n.sg-demo-open > .nav-dropdown-menu,\n.sg-demo-open > [role=\"menu\"],\n.sg-demo-open > .dropdown-menu {\n  display: block !important;\n  visibility: visible !important;\n  opacity: 1 !important;\n}\n\n/* ── Play/pause auto-advance button in walkthrough bar ── */\n.sg-wt-playpause {\n  font-size: 0.78rem;\n  padding: 3px 8px;\n  border: 1px solid rgba(201,168,76,0.4);\n  border-radius: 5px;\n  background: none;\n  color: #c9a84c;\n  cursor: pointer;\n  font-family: inherit;\n  line-height: 1;\n  transition: background 0.15s, border-color 0.15s;\n}\n.sg-wt-playpause:hover {\n  background: rgba(201,168,76,0.12);\n  border-color: #c9a84c;\n}\n\n/* ── Walkthrough navigator (step-tree) ── */\n.sg-wt-nav {\n  display: flex;\n  flex-direction: column;\n  gap: 2px;\n  max-height: 130px;\n  overflow-y: auto;\n  border-top: 1px solid #e8e0c8;\n  padding-top: 8px;\n  margin-top: 2px;\n  scrollbar-width: thin;\n  scrollbar-color: #c9a84c transparent;\n}\n.sg-wt-nav::-webkit-scrollbar { width: 4px; }\n.sg-wt-nav::-webkit-scrollbar-thumb { background: rgba(201,168,76,0.45); border-radius: 2px; }\n.sg-wt-nav-step {\n  background: #f0ece0;\n  border: 1px solid #e0d8c0;\n  border-radius: 6px;\n  padding: 4px 10px;\n  font-family: inherit;\n  font-size: 0.78rem;\n  color: #444;\n  cursor: pointer;\n  text-align: left;\n  line-height: 1.4;\n  white-space: nowrap;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  transition: background 0.15s, border-color 0.15s, color 0.15s;\n}\n.sg-wt-nav-step:hover {\n  background: #e8e0ca;\n  border-color: #b8963e;\n  color: #060e18;\n}\n.sg-wt-nav-step--current {\n  border-color: #c9a84c;\n  background: #f5eed8;\n  color: #060e18;\n  font-weight: 600;\n}\n.sg-wt-nav-step--sub {\n  margin-left: 14px;\n  font-size: 0.74rem;\n  color: #555;\n  background: #f8f5ef;\n  border-color: #e8e0cc;\n}\n.sg-wt-nav-step--sub:hover {\n  background: #ede7d3;\n  border-color: #b8963e;\n  color: #060e18;\n}\n.sg-wt-nav-step--sub.sg-wt-nav-step--current {\n  background: #f5eed8;\n  border-color: #c9a84c;\n  color: #060e18;\n  font-weight: 600;\n}\n\n/* ── Mobile responsive — ≤600px ── */\n@media (max-width: 600px) {\n  #soma-guide {\n    bottom: 14px;\n    right: 14px;\n  }\n\n  /* FAB — compact but still tappable */\n  .sg-fab {\n    padding: 10px 14px 10px 11px;\n    font-size: 0.82rem;\n    gap: 6px;\n  }\n  .sg-fab-avatar { font-size: 1.05rem; }\n\n  /* Expanded panel — stay within viewport, scrollable */\n  .sg--idle .sg-panel,\n  .sg--text .sg-panel,\n  .sg--walkthrough .sg-panel,\n  .sg--voice .sg-panel {\n    width: min(340px, calc(100vw - 28px));\n    max-height: min(72vh, 460px);\n  }\n\n  /* Text panel: fixed height, no resize handle (pinch/zoom handles zoom on mobile) */\n  .sg--text .sg-panel {\n    height: min(72vh, 460px);\n    resize: none;\n  }\n\n  /* Body: tighter padding saves vertical space */\n  .sg-body { padding: 12px; }\n\n  /* Walk-through nav — shorten scrollable area to save screen */\n  .sg-wt-nav { max-height: 100px; }\n\n  /* Resume steps list — same cap */\n  .sg-resume-steps { max-height: 140px; }\n\n  /* Close button — larger hit target on touch */\n  .sg-btn-close {\n    min-width: 36px !important;\n    min-height: 36px !important;\n    display: flex;\n    align-items: center;\n    justify-content: center;\n  }\n}\n\n/* ── Feedback topic buttons (affordance in idle/greeting list) ── */\n.sg-topic-btn--feedback {\n  background: #f0f4ff;\n  border-color: #c3cfe8;\n  color: #1a3060;\n}\n.sg-topic-btn--feedback:hover { background: #e3eaff; }\n\n/* ── Inline feedback capture form ── */\n.sg-feedback-form {\n  background: #f9f7f2;\n  border: 1px solid #e8dfc4;\n  border-radius: 10px;\n  padding: 14px;\n  display: flex;\n  flex-direction: column;\n  gap: 8px;\n  max-width: 100%;\n  width: 100%;\n  box-sizing: border-box;\n}\n.sg-feedback-form-title {\n  font-size: 0.88rem;\n  font-weight: 700;\n  color: #060e18;\n  margin-bottom: 2px;\n}\n.sg-feedback-label {\n  font-size: 0.78rem;\n  font-weight: 600;\n  color: #444;\n}\n.sg-feedback-textarea {\n  width: 100%;\n  box-sizing: border-box;\n  border: 1px solid #ddd;\n  border-radius: 6px;\n  padding: 8px 10px;\n  font-family: inherit;\n  font-size: 0.82rem;\n  color: #1a1a1a;\n  resize: vertical;\n  min-height: 72px;\n  background: #fff;\n}\n.sg-feedback-textarea:focus { outline: none; border-color: #c9a84c; }\n.sg-feedback-input {\n  width: 100%;\n  box-sizing: border-box;\n  border: 1px solid #ddd;\n  border-radius: 6px;\n  padding: 7px 10px;\n  font-family: inherit;\n  font-size: 0.82rem;\n  color: #1a1a1a;\n  background: #fff;\n}\n.sg-feedback-input:focus { outline: none; border-color: #c9a84c; }\n.sg-feedback-btn-row {\n  display: flex;\n  gap: 8px;\n  margin-top: 4px;\n}\n.sg-feedback-submit {\n  background: #060e18;\n  color: #c9a84c;\n  border: none;\n  border-radius: 6px;\n  padding: 7px 18px;\n  font-family: inherit;\n  font-size: 0.82rem;\n  font-weight: 600;\n  cursor: pointer;\n  transition: opacity 0.15s;\n}\n.sg-feedback-submit:hover { opacity: 0.85; }\n.sg-feedback-submit:disabled { opacity: 0.5; cursor: not-allowed; }\n.sg-feedback-cancel {\n  background: none;\n  border: 1px solid #ccc;\n  border-radius: 6px;\n  padding: 7px 14px;\n  font-family: inherit;\n  font-size: 0.82rem;\n  color: #666;\n  cursor: pointer;\n  transition: background 0.15s;\n}\n.sg-feedback-cancel:hover { background: #f0f0f0; }\n.sg-feedback-status {\n  font-size: 0.78rem;\n  color: #555;\n  min-height: 16px;\n}\n.sg-feedback-status--error { color: #c0392b; font-weight: 600; }\n";
